import{_ as t,o,c as r,a5 as a}from"./chunks/framework.DSg0KOwT.js";const g=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/getting-started.md","filePath":"user-guide/getting-started.md"}'),s={name:"user-guide/getting-started.md"};function n(d,e,i,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>SparkForensics reads a Spark History Server event log and turns it into a dashboard of flagged bottlenecks. No account needed.</p><h2 id="local-server-mode" tabindex="-1">Run it locally <a class="header-anchor" href="#local-server-mode" aria-label="Permalink to &quot;Run it locally {#local-server-mode}&quot;">​</a></h2><p>The recommended way to run SparkForensics on your machine:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sparkforensics-server</span></span></code></pre></div><p>Open <code>http://127.0.0.1:4173</code> and drop a log in. This is <strong>local-server mode</strong>: it also fetches runs from a Spark History Server on your behalf. Port and environment-variable overrides are in <a href="#server-configuration">Server configuration</a>. What changes for a static deploy is in the <a href="https://github.com/shuffle-works/sparkforensics#deploy-modes" target="_blank" rel="noreferrer">project README</a>.</p><p>The <a href="https://shuffle-works.github.io/sparkforensics/" target="_blank" rel="noreferrer">hosted demo</a> runs the same dashboard but can&#39;t fetch from a History Server. To work on SparkForensics itself, see <a href="./../contributor-guide/development-setup.html">Development setup</a>.</p><h3 id="server-configuration" tabindex="-1">Server configuration <a class="header-anchor" href="#server-configuration" aria-label="Permalink to &quot;Server configuration {#server-configuration}&quot;">​</a></h3><p>All settings have working defaults. Override them with environment variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>4173</code></td><td>Listen port, a whole number from 0 to 65535. The <code>--port</code> flag takes precedence. Another value, or an unknown flag, exits <code>2</code>; a port already in use exits <code>1</code>.</td></tr><tr><td><code>SPARKFORENSICS_SHS_BASE_URL</code></td><td>none</td><td>Default History Server URL. The CLI uses it for <code>--app-id</code> and <code>--baseline-app-id</code> when <code>--shs-base-url</code> or <code>--baseline-shs-base-url</code> is not given. <code>sparkforensics-mcp</code> uses it for a <code>source</code> or <code>list_runs</code> call without <code>shsBaseUrl</code>. A flag takes precedence.</td></tr><tr><td><code>SPARKFORENSICS_SHS_TIMEOUT_MS</code></td><td><code>30000</code></td><td>History Server fetch timeout. Response headers must arrive within this window, and a streaming body that goes idle this long is cut off. It applies to the <code>/shs-proxy</code> route and the MCP archive download. Progressing downloads of any size are unaffected.</td></tr><tr><td><code>SPARKFORENSICS_MCP_CACHE_CAP</code></td><td><code>8</code></td><td>Most parsed runs kept in the MCP tool cache.</td></tr><tr><td><code>SPARKFORENSICS_MCP_CACHE_TTL_MS</code></td><td><code>900000</code></td><td>Idle eviction time for cached MCP runs (15 minutes).</td></tr><tr><td><code>SPARKFORENSICS_MAX_ARCHIVE_BYTES</code></td><td><code>1073741824</code></td><td>Largest History Server event-log archive the MCP tools or the CLI&#39;s <code>--shs-base-url</code> mode buffer (1 GiB). A larger response fails with <code>archive-too-large</code>.</td></tr></tbody></table><h2 id="load-a-run" tabindex="-1">Load a run <a class="header-anchor" href="#load-a-run" aria-label="Permalink to &quot;Load a run&quot;">​</a></h2><p>Drop a log file onto the landing page, or click <strong>Choose file</strong> to pick one. Parsing runs in a background worker, off the browser&#39;s main thread, so a multi-hundred-megabyte event stream doesn&#39;t freeze the tab. While it runs, the progress screen shows how far along it is and roughly how long is left; <strong>Cancel</strong> returns to the landing page.</p><p>No log of your own yet? Click <strong>Try a sample run</strong> on the landing page to load a bundled example run and see a populated dashboard right away. A line above its verdict says it is the sample, with <strong>Load my event log</strong> and a link to where to find one, so you can switch to your own run from there. <strong>Where do I find my event log?</strong>, under the buttons, is a short guide to turning event logging on and downloading a log from a History Server.</p><p>The app takes a newline-delimited JSON event log (one JSON event per line, the format Spark writes to <code>spark.eventLog.dir</code>), either plain or gzip/Zstandard/LZ4/Snappy-compressed. It also takes the zip a Spark History Server hands back, from the Spark UI&#39;s download link or from <code>GET /api/v1/applications/&lt;appId&gt;/logs</code>, as-is: drop the <code>.zip</code> and the app unwraps the log inside it, or reassembles the parts of a rolling log. The zip must hold one attempt: for an application that ran more than once, download <code>/api/v1/applications/&lt;appId&gt;/&lt;attemptId&gt;/logs</code> instead. Spark&#39;s <code>lzf</code> codec is not supported: set <code>spark.eventLog.compression.codec</code> to <code>zstd</code>, <code>lz4</code> or <code>snappy</code>.</p><p>Click <strong>Other sources</strong> on the landing page for two more ways in:</p><ul><li><strong>Choose rolling-log folder</strong>, for an <code>eventlog_v2_*</code> rolling directory. Drop the folder or point the picker at it; the app reassembles its parts in order before parsing.</li><li><strong>Fetch from Spark History Server</strong>, to pull an application straight from a reachable History Server. This needs <strong>local-server mode</strong> (see <a href="#local-server-mode">Run it locally</a>) and an application ID in one of the forms Spark itself uses: <code>application_&lt;timestamp&gt;_&lt;id&gt;</code>, <code>local-&lt;timestamp&gt;</code>, <code>app-&lt;id&gt;</code>, <code>spark-&lt;id&gt;</code>, or <code>driver-&lt;id&gt;</code>. If the fetch fails, the panel names the problem (server unreachable, application not found, local server not running, and so on) and suggests what to try next.</li></ul><p>Can&#39;t reach the History Server directly (it&#39;s only reachable through an SSH bastion)? See <a href="./alternative-log-retrieval/ssh-bastion.html#behind-an-ssh-bastion">Behind an SSH bastion</a>.</p><p>In Chromium-based browsers, single files you open stay listed under <strong>Recent files</strong> on the landing page. Rolling-log folders, History Server fetches and the sample run are not listed.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in {#other-ways-in}&quot;">​</a></h2><p>The dashboard is one of several ways to use SparkForensics:</p><ul><li><strong>Command line and CI.</strong> The <code>sparkforensics-analyze</code> CLI reads the same event logs, prints a JSON or Markdown report, and exits non-zero when a run breaks a budget you set. See <a href="./getting-started/ci-and-automation.html">CI and automation</a>.</li><li><strong>AI assistants.</strong> The MCP server (<code>npx sparkforensics-mcp</code>) lets an agent diagnose, summarize and compare runs. See <a href="./mcp-tools.html">MCP tools reference</a>.</li><li><strong>Airflow.</strong> <a href="https://github.com/shuffle-works/sparkforensics-operator" target="_blank" rel="noreferrer">sparkforensics-operator</a> runs the analysis after every Spark job and acts on the result.</li></ul><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary {#glossary}&quot;">​</a></h2><p>Terms used across the user guide:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>AQE</td><td>Adaptive Query Execution. Spark re-plans a query at run time, for example to split a skewed join or coalesce small shuffle partitions.</td></tr><tr><td>P95</td><td>The 95th percentile: 95% of the values are at or below it. For task times, it is the duration that only the slowest 5% of tasks exceed.</td></tr><tr><td>SHS</td><td>Spark History Server, the service that serves the event logs of finished applications.</td></tr><tr><td>Core-hours</td><td>The sum, over executors, of cores times the hours each executor was alive. It measures the compute a run reserved, not the compute it used. See <a href="./getting-started/ci-and-automation.html#allocation">Allocation</a>.</td></tr><tr><td>GB-h</td><td>Gigabyte-hours: executor memory times the hours the executor was alive. The report calls it <code>memoryGbHours</code>.</td></tr><tr><td>Core-milliseconds</td><td>The unit of executor core time. One core busy for one millisecond is one core-millisecond.</td></tr><tr><td>Stage fingerprint</td><td>The key that identifies a stage: its normalized name plus its plan nodes. The same stage has the same fingerprint in two runs, so a comparison can pair them.</td></tr><tr><td>NDJSON</td><td>Newline-delimited JSON: one JSON value per line. Spark writes event logs in this format, and the CLI uses it to report several candidates.</td></tr><tr><td>Sequence alignment</td><td>The method a comparison uses to pair SQL executions and stages across two runs. It keeps the submission order and picks the best-scoring pairs. See <a href="./run-comparison/how-stages-are-matched.html">How stages are matched</a>.</td></tr><tr><td>Confidence</td><td>How sure a detector is that a finding is real. It scales with how far the measured value is past the threshold and with the sample size. <a href="./getting-started/reading-the-dashboard.html#advanced-view">Advanced view</a> shows it when it is below high.</td></tr></tbody></table>',24)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
